<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetTypeVO;

trait TemplateAssetTypeAccessor {
  private TemplateAssetTypeVO $_type;
  public function getType(): string
  {
    return $this->_type->value();
  }
  public function type(): TemplateAssetTypeVO
  {
    return $this->_type;
  }
  public function isTypeChanged(?self $original = null): bool
  {
  return !$this->_type->equals( $original?->_type );  }
  public function withType(TemplateAssetTypeVO|string $type): self
  {
    $copy = clone $this;
    $copy->_type = TemplateAssetTypeVO::from( $type );
    return $copy;
  }
}